/**
 * Unit tests for DateTimeZone.forOffsetHoursMinutes
 */
public class DateTimeZone_forOffsetHoursMinutes_TriageGen0Test {

    @Test
    public void testForOffsetHoursMinutes_ZeroMinutesReturnsUTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // Test +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedOffsetMillis = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30
        // Logic: hoursInMinutes = -300. minutesOffset = -300 - abs(-30) = -330.
        // Wait, the implementation logic for negative is: minutesOffset = hoursInMinutes - Math.abs(minutesOffset)
        // If input is hoursOffset = -5, minutesOffset = -30
        // hoursInMinutes = -300. minutesOffset = -300 - 30 = -330 mins.
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, -30);
        int expectedOffsetMillis = (-5 * 60 - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeHoursZeroMinutes() {
        // Even if hours are negative, if minutes are 0, it returns UTC per code
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(5, 60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        DateTimeZone.forOffsetHoursMinutes(5, -60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_PositiveHoursNegativeMinutes() {
        // "Positive hours must not have negative minutes"
        DateTimeZone.forOffsetHoursMinutes(5, -30);
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryHoursMax() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(23, 59);
        int expectedOffsetMillis = (23 * 60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryHoursMin() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-23, -59);
        int expectedOffsetMillis = (-23 * 60 - 59) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_ZeroHoursPositiveMinutes() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 30);
        int expectedOffsetMillis = 30 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_ZeroHoursNegativeMinutes() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, -30);
        int expectedOffsetMillis = -30 * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedOffsetMillis, zone.getOffset(0));
    }
}
